#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    vector<vector<ll>> test(t);
    vector<int> ns(t);
    int maxn =0;
    for(int tc =0; tc <t ;tc++) {
        int n;
        cin>>n;
        ns[tc] = n;
        maxn = max(maxn,n) ;
        test[tc].resize(n);
        for(int i =0; i <n; i++) {
            cin>>test[tc][i];
            test[tc][i] %= MOD;
            
        }
    }
    vector<ll> inv(maxn +1);
    if(maxn >= 1) {
        inv[1] =1;
    }
    for(int i =2; i <= maxn;i++ ) {
        inv[i]= MOD - (MOD / i) * inv[MOD % i] % MOD;
    }
    vector<ll>h(maxn +1,0);
    for(int i =1; i <= maxn; i++) {
        h[i] = (h[i-1] + inv[i]) % MOD;
    }
    for(int tc =0; tc < t; tc++) {
        int n = ns[tc];
        vector<ll> & a = test[tc];
        ll ans =0;
        for(int i =1; i <= n; i++) {
            ll coeff = (h[i-1] +h[n-i]) % MOD;
            ans = (ans + a[i -1] * coeff) % MOD;
            
        }
        cout<<ans<<endl;
    }
    return 0;
    // your code goes here

}
